{"operationName":"CreateFeedsManager","query":"
mutation CreateFeedsManager ($input: CreateFeedsManagerInput!) {
	createFeedsManager(input: $input) {
		__typename
		... on CreateFeedsManagerSuccess {
			feedsManager {
				... FeedsManagerParts
			}
		}
		... on SingleFeedsManagerError {
			message
			code
		}
		... on NotFoundError {
			message
			code
		}
		... on InputErrors {
			errors {
				message
				code
				path
			}
		}
	}
}
fragment FeedsManagerParts on FeedsManager {
	id
	name
	uri
	publicKey
	isConnectionActive
	createdAt
	jobProposals {
		id
		status
		remoteUUID
		externalJobID
		jobID
		specs {
			id
			definition
			version
			status
			statusUpdatedAt
			createdAt
			updatedAt
		}
		latestSpec {
			id
			definition
			version
			status
			statusUpdatedAt
			createdAt
			updatedAt
		}
	}
}
